import re

class JSONParseError(ValueError):
    pass

def parse_json(json_str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises JSONParseError.
    """
    # Token patterns
    _WHITESPACE = r'[ \t\r\n]*'
    _STRING = r'"(?:[^"\\]|\\["\\/bfnrt\\]|\\u[0-9a-fA-F]{4})*"'
    _NUMBER = r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?'
    _TRUE = r'true'
    _FALSE = r'false'
    _NULL = r'null'
    _TOKEN_RE = re.compile(
        r'[ \t\r\n]*'                     # skip leading whitespace before each token
        r'(?P<string>' + _STRING + r')|'
        r'(?P<number>' + _NUMBER + r')|'
        r'(?P<true>'   + _TRUE   + r')|'
        r'(?P<false>'  + _FALSE  + r')|'
        r'(?P<null>'   + _NULL   + r')|'
        r'(?P<lbrace>\{)|'
        r'(?P<rbrace>\})|'
        r'(?P<lbracket>\[)|'
        r'(?P<rbracket>\])|'
        r'(?P<colon>:)|'
        r'(?P<comma>,)'
    )

    # Helper to decode escape sequences in JSON strings
    _ESCAPE_RE = re.compile(r'\\(["\\/bfnrt\\])|\\u([0-9a-fA-F]{4})')
    _ESCAPE_MAP = {
        '"': '"', '\\': '\\', '/': '/', 'b': '\b',
        'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
    }

    def _decode_string(s):
        def repl(m):
            ch = m.group(1)
            if ch:
                return _ESCAPE_MAP[ch]
            return chr(int(m.group(2), 16))
        return _ESCAPE_RE.sub(repl, s[1:-1])   # strip surrounding quotes

    # Token generator
    def _tokenize(s):
        pos = 0
        length = len(s)
        while pos < length:
            m = _TOKEN_RE.match(s, pos)
            if not m:
                # If only whitespace remains, treat as end of input
                if s[pos:].strip() == '':
                    break
                raise JSONParseError(f'Invalid token at position {pos}')
            pos = m.end()
            # Yield the first matched named group (skip pure whitespace)
            for name, value in m.groupdict().items():
                if value is not None:
                    yield name, value
                    break
        yield 'eof', ''

    # Recursive‑descent parser
    tokens = _tokenize(json_str)
    lookahead_type, lookahead_val = next(tokens)

    def _consume(expected_type):
        nonlocal lookahead_type, lookahead_val
        if lookahead_type != expected_type:
            raise JSONParseError(f'Expected {expected_type} but found {lookahead_type}')
        cur_val = lookahead_val
        lookahead_type, lookahead_val = next(tokens)
        return cur_val

    def parse_value():
        if lookahead_type == 'string':
            return _decode_string(_consume('string'))
        if lookahead_type == 'number':
            num_str = _consume('number')
            return int(num_str) if '.' not in num_str and 'e' not in num_str and 'E' not in num_str else float(num_str)
        if lookahead_type == 'true':
            _consume('true')
            return True
        if lookahead_type == 'false':
            _consume('false')
            return False
        if lookahead_type == 'null':
            _consume('null')
            return None
        if lookahead_type == 'lbrace':
            return parse_object()
        if lookahead_type == 'lbracket':
            return parse_array()
        raise JSONParseError(f'Unexpected token {lookahead_type}')

    def parse_array():
        _consume('lbracket')
        arr = []
        if lookahead_type == 'rbracket':
            _consume('rbracket')
            return arr
        while True:
            arr.append(parse_value())
            if lookahead_type == 'comma':
                _consume('comma')
                continue
            if lookahead_type == 'rbracket':
                _consume('rbracket')
                break
            raise JSONParseError('Expected , or ] in array')
        return arr

    def parse_object():
        _consume('lbrace')
        obj = {}
        if lookahead_type == 'rbrace':
            _consume('rbrace')
            return obj
        while True:
            if lookahead_type != 'string':
                raise JSONParseError('Object keys must be strings')
            key = _decode_string(_consume('string'))
            if lookahead_type != 'colon':
                raise JSONParseError('Missing colon after object key')
            _consume('colon')
            obj[key] = parse_value()
            if lookahead_type == 'comma':
                _consume('comma')
                continue
            if lookahead_type == 'rbrace':
                _consume('rbrace')
                break
            raise JSONParseError('Expected , or } in object')
        return obj

    result = parse_value()
    if lookahead_type != 'eof':
        raise JSONParseError('Extra data after valid JSON')
    return result

