import re

class JSONParseError(ValueError):
    """Exception raised for errors in the JSON parsing process."""
    pass

def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure.

    Raises:
        JSONParseError: If the input is not valid JSON.
    """
    # Token specifications (order matters)
    _TOKEN_SPEC = [
        ('WHITESPACE', r'[ \t\r\n]+'),                     # Skip whitespace
        ('TRUE',       r'true\b'),                        # true literal
        ('FALSE',      r'false\b'),                       # false literal
        ('NULL',       r'null\b'),                        # null literal
        ('NUMBER',     r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?'),  # number
        ('STRING',     r'"(?:\\["\\/bfnrt]|\\u[0-9a-fA-F]{4}|[^"\\])*"'), # string
        ('LBRACE',     r'\{'),                            # {
        ('RBRACE',     r'\}'),                            # }
        ('LBRACKET',   r'\['),                            # [
        ('RBRACKET',   r'\]'),                            # ]
        ('COMMA',      r','),                             # ,
        ('COLON',      r':'),                             # :
    ]

    _MASTER_RE = re.compile('|'.join('(?P<%s>%s)' % pair for pair in _TOKEN_SPEC))

    # ----------------------------------------------------------------------
    # Lexer – converts the raw string into a stream of (type, value) tokens
    # ----------------------------------------------------------------------
    def _lex(s):
        pos = 0
        while pos < len(s):
            m = _MASTER_RE.match(s, pos)
            if not m:
                raise JSONParseError(f'Invalid token at position {pos}: {s[pos:pos+20]!r}')
            typ = m.lastgroup
            val = m.group(typ)
            if typ != 'WHITESPACE':
                yield typ, val
            pos = m.end()
        yield 'EOF', ''

    # ----------------------------------------------------------------------
    # Recursive‑descent parser
    # ----------------------------------------------------------------------
    class Parser:
        def __init__(self, tokens):
            self.tokens = iter(tokens)
            self.tok_type, self.tok_val = next(self.tokens)

        def _advance(self):
            self.tok_type, self.tok_val = next(self.tokens)

        def _expect(self, expected_type):
            if self.tok_type != expected_type:
                raise JSONParseError(f'Expected {expected_type} but found {self.tok_type}')
            val = self.tok_val
            self._advance()
            return val

        # entry point
        def parse(self):
            result = self._value()
            if self.tok_type != 'EOF':
                raise JSONParseError('Extra data after valid JSON')
            return result

        # value = false / null / true / object / array / number / string
        def _value(self):
            if self.tok_type == 'LBRACE':
                return self._object()
            if self.tok_type == 'LBRACKET':
                return self._array()
            if self.tok_type == 'STRING':
                return self._string()
            if self.tok_type == 'NUMBER':
                return self._number()
            if self.tok_type == 'TRUE':
                self._advance()
                return True
            if self.tok_type == 'FALSE':
                self._advance()
                return False
            if self.tok_type == 'NULL':
                self._advance()
                return None
            raise JSONParseError(f'Unexpected token {self.tok_type}')

        # object = begin-object [ member *( "," member ) ] end-object
        def _object(self):
            obj = {}
            self._expect('LBRACE')
            if self.tok_type == 'RBRACE':
                self._advance()
                return obj
            while True:
                if self.tok_type != 'STRING':
                    raise JSONParseError('Object keys must be strings')
                key = self._string()
                self._expect('COLON')
                value = self._value()
                if key in obj:
                    raise JSONParseError(f'Duplicate key {key!r} in object')
                obj[key] = value
                if self.tok_type == 'COMMA':
                    self._advance()
                    continue
                elif self.tok_type == 'RBRACE':
                    self._advance()
                    break
                else:
                    raise JSONParseError('Expected "," or "}" in object')
            return obj

        # array = begin-array [ value *( "," value ) ] end-array
        def _array(self):
            arr = []
            self._expect('LBRACKET')
            if self.tok_type == 'RBRACKET':
                self._advance()
                return arr
            while True:
                arr.append(self._value())
                if self.tok_type == 'COMMA':
                    self._advance()
                    continue
                elif self.tok_type == 'RBRACKET':
                    self._advance()
                    break
                else:
                    raise JSONParseError('Expected "," or "]" in array')
            return arr

        # string = quotation-mark *char quotation-mark
        def _string(self):
            raw = self._expect('STRING')
            # Strip the surrounding quotes
            s = raw[1:-1]

            # Replace escape sequences
            def replace_escape(match):
                esc = match.group(0)
                if esc[1] in '"\\/bfnrt':
                    return {
                        '"': '"',
                        '\\': '\\',
                        '/': '/',
                        'b': '\b',
                        'f': '\f',
                        'n': '\n',
                        'r': '\r',
                        't': '\t',
                    }[esc[1]]
                # Unicode escape \uXXXX
                return chr(int(esc[2:], 16))

            s = re.sub(r'\\(["\\/bfnrt])|\\u[0-9a-fA-F]{4}', replace_escape, s)
            return s

        # number = int [ frac ] [ exp ]
        def _number(self):
            num_str = self._expect('NUMBER')
            # Decide int vs float according to RFC
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                try:
                    return float(num_str)
                except ValueError:
                    raise JSONParseError(f'Invalid float literal {num_str}')
            else:
                try:
                    return int(num_str)
                except ValueError:
                    raise JSONParseError(f'Invalid integer literal {num_str}')

