class JSONParseError(ValueError):
    """Exception raised for errors in the JSON parsing process."""
    pass

def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure.

    Raises:
        JSONParseError: If the input is not valid JSON.
