        if ch == '[':                     # array
            return _parse_array(i)

        if ch in '-0123456789':           # number
            m = _NUMBER.match(json_str, i)
            if not m:
                raise JSONParseError(f"Invalid number at position {i}")
            num_str = m.group()
            i = m.end()
