def parse_json(json_str):
    """
    Minimal JSON parser compliant with RFC 8259.
    Supports objects, arrays, strings, numbers, true, false, null.
    Raises ValueError on any syntax error.
    """
    import re

    # Token specifications
    _WHITESPACE = re.compile(r'\s*')
    _STRING = re.compile(r'"(?:\\["\\/bfnrt]|\\u[0-9a-fA-F]{4}|[^"\\])*"')
    _NUMBER = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?', re.ASCII)

    # Helper to skip whitespace and return next position
    def _skip_ws(i):
        if i >= len(json_str):
            return i
        m = _WHITESPACE.match(json_str, i)
        return m.end()

    # Decode a JSON string literal (without surrounding quotes) with surrogate‑pair handling
    def _decode_string(s):
        # replace escape sequences
        def replace(match):
            esc = match.group(0)
            if esc[1] in '"\\/bfnrt':
                return {
                    '"': '"',
                    '\\': '\\',
                    '/': '/',
                    'b': '\b',
                    'f': '\f',
                    'n': '\n',
                    'r': '\r',
                    't': '\t',
                }[esc[1]]
            elif esc[1] == 'u':
                return chr(int(esc[2:], 16))
            else:  # should never happen
                raise ValueError('Invalid escape sequence')
        decoded = re.sub(r'\\(["\\/bfnrt]|u[0-9a-fA-F]{4})', replace, s)

        # combine UTF‑16 surrogate pairs into a single code point
        out = []
        i = 0
        while i < len(decoded):
            ch = decoded[i]
            if 0xD800 <= ord(ch) <= 0xDBFF and i + 1 < len(decoded):
                nxt = decoded[i + 1]
                if 0xDC00 <= ord(nxt) <= 0xDFFF:
                    code = 0x10000 + ((ord(ch) - 0xD800) << 10) + (ord(nxt) - 0xDC00)
                    out.append(chr(code))
                    i += 2
                    continue
            out.append(ch)
            i += 1
        return ''.join(out)

    # Recursive descent parser
    def _parse_value(i):
        i = _skip_ws(i)
