import re

class JSONParseError(ValueError):
    pass

def parse_json(json_str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises JSONParseError.
    """
    # Token specification
    _WHITESPACE = r'[ \t\n\r]*'
    _STRING = r'"(?:\\["\\/bfnrt]|\\u[0-9a-fA-F]{4}|[^"\\])*"'
    _NUMBER = r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?'
    _TRUE = r'true'
    _FALSE = r'false'
    _NULL = r'null'
    _LBRACE = r'\{'
    _RBRACE = r'\}'
    _LBRACK = r'\['
    _RBRACK = r'\]'
    _COMMA = r','
    _COLON = r':'

    _TOKEN_RE = re.compile(
        f'({_WHITESPACE})('
        f'(?P<string>{_STRING})|'
        f'(?P<number>{_NUMBER})|'
        f'(?P<true>{_TRUE})|'
        f'(?P<false>{_FALSE})|'
        f'(?P<null>{_NULL})|'
        f'(?P<lbrace>{_LBRACE})|'
        f'(?P<rbrace>{_RBRACE})|'
        f'(?P<lbrack>{_LBRACK})|'
        f'(?P<rbrack>{_RBRACK})|'
        f'(?P<comma>{_COMMA})|'
        f'(?P<colon>{_COLON})'
        f')'
    )

    # Lexer – converts the input string into a list of (type, value) tokens
    def _lex(s):
        pos = 0
        tokens = []
        while pos < len(s):
            m = _TOKEN_RE.match(s, pos)
            if not m:
                raise JSONParseError(f'Invalid token at position {pos}')
            # skip whitespace (group 1)
            typ = m.lastgroup
            if typ:
                val = m.group(typ)
                tokens.append((typ, val))
            pos = m.end()
        tokens.append(('EOF', None))
        return tokens

    # Recursive‑descent parser
    class _Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def _peek(self):
            return self.tokens[self.pos][0]

        def _next(self):
            typ, val = self.tokens[self.pos]
            self.pos += 1
            return typ, val

        def _expect(self, expected_type):
            typ, val = self._next()
            if typ != expected_type:
                raise JSONParseError(f'Expected {expected_type} but got {typ}')
            return val

        def parse(self):
            value = self._value()
            if self._peek() != 'EOF':
                raise JSONParseError('Extra data after valid JSON')
            return value

        def _value(self):
            typ = self._peek()
            if typ == 'string':
                return self._string()
            if typ == 'number':
                return self._number()
            if typ == 'lbrace':
                return self._object()
            if typ == 'lbrack':
                return self._array()
            if typ == 'true':
                self._next()
                return True
            if typ == 'false':
                self._next()
                return False
            if typ == 'null':
                self._next()
                return None
            raise JSONParseError(f'Unexpected token {typ}')

        def _string(self):
            _, raw = self._next()
            # Unescape according to RFC 8259
            def replace_escape(match):
                esc = match.group(1)
                if esc == '"':   return '"'
                if esc == '\\':  return '\\'
                if esc == '/':   return '/'
                if esc == 'b':   return '\b'
                if esc == 'f':   return '\f'
                if esc == 'n':   return '\n'
                if esc == 'r':   return '\r'
                if esc == 't':   return '\t'
                if esc.startswith('u'):
                    return chr(int(esc[1:], 16))
                return esc

            inner = raw[1:-1]                     # strip surrounding quotes
            unescaped = re.sub(r'\\(["\\/bfnrt]|u[0-9a-fA-F]{4})',
                               replace_escape, inner)

            # ----- removed incorrect validation -----
            # if '\\' in unescaped:
            #     raise JSONParseError('Invalid escape sequence in string')
            # -----------------------------------------

            return unescaped

        def _number(self):
            _, raw = self._next()
            if '.' in raw or 'e' in raw or 'E' in raw:
                return float(raw)
            else:
                return int(raw)

        def _array(self):
            self._expect('lbrack')
            arr = []
            if self._peek() == 'rbrack':
                self._expect('rbrack')
                return arr
            while True:
                arr.append(self._value())
                if self._peek() == 'comma':
                    self._expect('comma')
                else:
                    break
            self._expect('rbrack')
            return arr

        def _object(self):
            self._expect('lbrace')
            obj = {}
