def parse_json(json_str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises JSONParseError.
    """
    # Token patterns
    _WHITESPACE = re.compile(r'\s*', re.ASCII)
    _STRING = re.compile(r'"(?:\\["\\/bfnrt]|\\u[0-9a-fA-F]{4}|[^"\\])*"', re.ASCII)
    _NUMBER = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?', re.ASCII)
    _TRUE = re.compile(r'true')
    _FALSE = re.compile(r'false')
    _NULL = re.compile(r'null')

    s = json_str
    i = 0
    n = len(s)

    def skip_ws(pos):
        m = _WHITESPACE.match(s, pos)
        return m.end()

    def peek(pos):
        pos = skip_ws(pos)
        return s[pos] if pos < n else ''

    def consume_literal(pos, pattern, value):
        m = pattern.match(s, pos)
        if not m:
            raise JSONParseError(f'Expected {value!r} at position {pos}')
        return m.end(), value

    def parse_value(pos):
        pos = skip_ws(pos)
        if pos >= n:
            raise JSONParseError('Unexpected end of input while parsing value')

        ch = s[pos]

        if ch == '"':
            return parse_string(pos)
        if ch == '{':
            return parse_object(pos)
        if ch == '[':
            return parse_array(pos)
        if ch == 't':
            return consume_literal(pos, _TRUE, True)
        if ch == 'f':
            return consume_literal(pos, _FALSE, False)
        if ch == 'n':
            return consume_literal(pos, _NULL, None)
        if ch == '-' or ch.isdigit():
            return parse_number(pos)

        raise JSONParseError(f'Invalid character {ch!r} at position {pos}')

    def parse_string(pos):
        m = _STRING.match(s, pos)
        if not m:
            raise JSONParseError(f'Invalid string at position {pos}')
        raw = m.group()
        # Decode escape sequences
        def replace_escape(match):
            esc = match.group(1)
            if esc == '"':   return '"'
            if esc == '\\':  return '\\'
            if esc == '/':   return '/'
            if esc == 'b':   return '\b'
            if esc == 'f':   return '\f'
            if esc == 'n':   return '\n'
            if esc == 'r':   return '\r'
            if esc == 't':   return '\t'
            if esc.startswith('u'):
                return chr(int(esc[1:], 16))
            return esc  # should never happen
        inner = raw[1:-1]
        inner = re.sub(r'\\(["\\/bfnrt]|u[0-9a-fA-F]{4})', replace_escape, inner)
        # Verify no unescaped control characters (U+0000‑U+001F)
        if any(ord(ch) < 0x20 for ch in inner):
            raise JSONParseError(f'Unescaped control character in string at position {pos}')
        return m.end(), inner

    def parse_number(pos):
        m = _NUMBER.match(s, pos)
        if not m:
            raise JSONParseError(f'Invalid number at position {pos}')
        num_str = m.group()
        # Choose int vs float according to RFC
        if '.' in num_str or 'e' in num_str or 'E' in num_str:
            value = float(num_str)
        else:
            value = int(num_str)
        return m.end(), value

    def parse_array(pos):
        if s[pos] != '[':
            raise JSONParseError(f'Expected "[" at position {pos}')
        pos += 1
        arr = []
        pos = skip_ws(pos)
        if pos < n and s[pos] == ']':
            return pos + 1, arr  # empty array

        while True:
            pos, value = parse_value(pos)
            arr.append(value)
            pos = skip_ws(pos)
            if pos >= n:
                raise JSONParseError('Unterminated array')
            if s[pos] == ',':
                pos += 1
                continue
            if s[pos] == ']':
                return pos + 1, arr
            raise JSONParseError(f'Expected "," or "]" in array at position {pos}')

    def parse_object(pos):
        if s[pos] != '{':
            raise JSONParseError(f'Expected "{{" at position {pos}')
        pos += 1
        obj = {}
        pos = skip_ws(pos)
        if pos < n and s[pos] == '}':
            return pos + 1, obj  # empty object

        while True:
            # key must be a string
            pos, key = parse_string(pos)
            pos = skip_ws(pos)
            if pos >= n or s[pos] != ':':
                raise JSONParseError(f'Expected ":" after object key at position {pos}')
            pos += 1
            pos, value = parse_value(pos)
            if key in obj:
                raise JSONParseError(f'Duplicate key {key!r} in object')
            obj[key] = value
            pos = skip_ws(pos)
            if pos >= n:
                raise JSONParseError('Unterminated object')
            if s[pos] == ',':
                pos += 1
                continue
            if s[pos] == '}':
                return pos + 1, obj
            raise JSONParseError(f'Expected "," or "}}" in object at position {pos}')

    # Start parsing
    final_pos, result = parse_value(0)
    final_pos = skip_ws(final_pos)
    if final_pos != n:
        raise JSONParseError(f'Extra data after valid JSON at position {final_pos}')
    return result

