        raw = m.group(0)
        # Decode escape sequences
        def replace_escape(match):
            esc = match.group(0)
            if esc[1] in '"\\/bfnrt':
                return {
                    '"': '"', '\\': '\\', '/': '/', 'b': '\b',
                    'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }[esc[1]]
            # Unicode escape \uXXXX
            return chr(int(esc[2:], 16))
        decoded = re.sub(r'\\(["\\/bfnrt]|u[0-9a-fA-F]{4})', replace_escape, raw[1:-1])
        return m.end(), decoded

    def parse_number(pos):
        m = _NUMBER.match(s, pos)
        if not m:
            raise JSONParseError(f'Invalid number at position {pos}')
        num_str = m.group(0)
        # Choose int vs float according to RFC
        if '.' in num_str or 'e' in num_str or 'E' in num_str:
            value = float(num_str)
        else:
            value = int(num_str)
        return m.end(), value

    def parse_array(pos):
        if s[pos] != '[':
            raise JSONParseError(f'Expected "[" at position {pos}')
        pos += 1
        arr = []
        pos = skip_ws(pos)
        if pos < n and s[pos] == ']':
            return pos + 1, arr  # empty array

        while True:
            pos, value = parse_value(pos)
            arr.append(value)
            pos = skip_ws(pos)
            if pos >= n:
                raise JSONParseError('Unexpected end of input inside array')
            if s[pos] == ',':
                pos += 1
                continue
            if s[pos] == ']':
                return pos + 1, arr
            raise JSONParseError(f'Expected "," or "]" in array at position {pos}')

    def parse_object(pos):
        if s[pos] != '{':
            raise JSONParseError(f'Expected "{{" at position {pos}')
        pos += 1
        obj = {}
        pos = skip_ws(pos)
        if pos < n and s[pos] == '}':
            return pos + 1, obj  # empty object

        while True:
            pos = skip_ws(pos)
            if pos >= n or s[pos] != '"':
                raise JSONParseError(f'Expected string key at position {pos}')
            pos, key = parse_string(pos)
            pos = skip_ws(pos)
            if pos >= n or s[pos] != ':':
                raise JSONParseError(f'Expected ":" after key at position {pos}')
            pos += 1
            pos, value = parse_value(pos)
            if key in obj:
                raise JSONParseError(f'Duplicate key {key!r} at position {pos}')
            obj[key] = value
            pos = skip_ws(pos)
            if pos >= n:
                raise JSONParseError('Unexpected end of input inside object')
            if s[pos] == ',':
                pos += 1
                continue
            if s[pos] == '}':
                return pos + 1, obj
            raise JSONParseError(f'Expected "," or "}}" in object at position {pos}')

    # Start parsing
    final_pos, result = parse_value(0)
    final_pos = skip_ws(final_pos)
    if final_pos != n:
        raise JSONParseError(f'Extra data after valid JSON at position {final_pos}')
    return result
